-- =====================================================================
-- BILBILASH ALUMNI COMMUNITY MANAGEMENT SYSTEM — PostgreSQL schema
-- (Supabase-compatible. Ported field-for-field from database/schema.sql)
--
-- Idempotent: safe to run multiple times (CREATE ... IF NOT EXISTS everywhere;
-- updated_at triggers are DROPped-if-exists and recreated — objects only, no
-- data is ever dropped or truncated).
-- Encoding: UTF8 (PostgreSQL default). Naming: snake_case (unchanged).
--
-- Mapping rules applied (MySQL → PostgreSQL), each deliberate:
--   AUTO_INCREMENT            → GENERATED BY DEFAULT AS IDENTITY
--   BIGINT/INT UNSIGNED       → BIGINT/INTEGER + CHECK (>= 0) where non-negative
--   TINYINT(1) (0/1 flags)    → SMALLINT + CHECK (IN (0,1))
--                                (preserves every "= 1 / = 0" query and the
--                                 mysql2-style 0/1 values the JS code expects)
--   ENUM(...)                 → TEXT + CHECK (IN (…same values…))
--                                (identical allowed-value enforcement, easier
--                                 to extend than a native PG enum type)
--   DATETIME / TIMESTAMP      → TIMESTAMP (without time zone) + parsers in
--                                db/pool.js return 'YYYY-MM-DD HH:MM:SS'
--                                strings exactly like mysql2 dateStrings:true
--   JSON                      → JSONB
--   ON UPDATE CURRENT_TIMESTAMP on updated_at → set_updated_at() trigger
--   FK / UNIQUE / INDEX names → kept identical for traceability
--
-- NOTE: this file does NOT create or select a database. The target database
-- is whatever DATABASE_URL (or DB_NAME) points to — `npm run init-db`
-- applies this file.
-- =====================================================================

-- updated_at auto-refresh (replaces MySQL's ON UPDATE CURRENT_TIMESTAMP)
CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger AS $$
BEGIN
  NEW.updated_at := CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TABLE IF NOT EXISTS roles (
  role_id     INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  role_name   TEXT NOT NULL,
  description VARCHAR(100) NULL,
  created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_roles_name UNIQUE (role_name),
  CONSTRAINT ck_roles_name CHECK (role_name IN ('VISITOR','MEMBER','ADMIN','AUTHORITY'))
);

CREATE TABLE IF NOT EXISTS users (
  user_id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  role_id        INTEGER NOT NULL,
  first_name     VARCHAR(60)  NOT NULL,
  last_name      VARCHAR(60)  NOT NULL,
  email          VARCHAR(120) NOT NULL,
  password_hash  VARCHAR(100) NOT NULL,
  phone          VARCHAR(20)  NULL,
  registration_number VARCHAR(50) NULL,
  status         TEXT NOT NULL DEFAULT 'pending',
  is_active      SMALLINT NOT NULL DEFAULT 1,
  token_version  INTEGER NOT NULL DEFAULT 0,
  created_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_users_email UNIQUE (email),
  CONSTRAINT uq_users_registration UNIQUE (registration_number),
  CONSTRAINT ck_users_status CHECK (status IN ('pending','approved','rejected','inactive')),
  CONSTRAINT ck_users_is_active CHECK (is_active IN (0,1)),
  CONSTRAINT ck_users_token_version CHECK (token_version >= 0),
  CONSTRAINT fk_users_role FOREIGN KEY (role_id) REFERENCES roles(role_id) ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_users_status ON users (status);
CREATE INDEX IF NOT EXISTS idx_users_role ON users (role_id);
DROP TRIGGER IF EXISTS trg_users_updated_at ON users;
CREATE TRIGGER trg_users_updated_at BEFORE UPDATE ON users
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE IF NOT EXISTS profiles (
  profile_id    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id       BIGINT NOT NULL,
  ssc_batch     INTEGER NULL,
  blood_group   TEXT NULL,
  profession    VARCHAR(120) NULL,
  institute     VARCHAR(120) NULL,
  address       VARCHAR(255) NULL, -- deprecated: superseded by present_address/permanent_address
  present_address VARCHAR(255) NULL,
  permanent_address VARCHAR(255) NULL,
  bio           VARCHAR(500) NULL,
  facebook_url  VARCHAR(255) NULL, -- optional public Facebook profile link
  active_donor  SMALLINT NOT NULL DEFAULT 0, -- member opted in as a blood donor (1 = yes)
  contribution_start_month CHAR(7) NULL, -- 'YYYY-MM' first obligated month; NULL = UNKNOWN (never guessed)
  profile_photo VARCHAR(255) NULL,
  created_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_profiles_user UNIQUE (user_id),
  CONSTRAINT ck_profiles_ssc_batch CHECK (ssc_batch IS NULL OR ssc_batch >= 0),
  CONSTRAINT ck_profiles_blood CHECK (blood_group IS NULL OR blood_group IN ('A+','A-','B+','B-','AB+','AB-','O+','O-')),
  CONSTRAINT ck_profiles_donor CHECK (active_donor IN (0,1)),
  CONSTRAINT fk_profiles_user FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_profiles_batch ON profiles (ssc_batch);
CREATE INDEX IF NOT EXISTS idx_profiles_blood ON profiles (blood_group);
CREATE INDEX IF NOT EXISTS idx_profiles_profession ON profiles (profession);
DROP TRIGGER IF EXISTS trg_profiles_updated_at ON profiles;
CREATE TRIGGER trg_profiles_updated_at BEFORE UPDATE ON profiles
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE IF NOT EXISTS password_resets (
  reset_id   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id    BIGINT NOT NULL,
  otp_hash   VARCHAR(100) NOT NULL,
  expires_at TIMESTAMP NOT NULL,
  used_at    TIMESTAMP NULL,
  attempts   INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT ck_pr_attempts CHECK (attempts >= 0),
  CONSTRAINT fk_pr_user FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_pr_user ON password_resets (user_id);

CREATE TABLE IF NOT EXISTS jobs (
  job_id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  posted_by        BIGINT NOT NULL,
  title            VARCHAR(150) NOT NULL,
  company          VARCHAR(120) NOT NULL,
  description      TEXT NOT NULL,
  location         VARCHAR(120) NULL,
  employment_type  TEXT NOT NULL DEFAULT 'full-time',
  salary           VARCHAR(80) NULL,
  application_info VARCHAR(255) NULL,
  deadline         DATE NULL,
  status           TEXT NOT NULL DEFAULT 'pending',
  created_at       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT ck_jobs_employment CHECK (employment_type IN ('full-time','part-time','contract','internship','remote')),
  CONSTRAINT ck_jobs_status CHECK (status IN ('pending','approved','rejected','closed')),
  CONSTRAINT fk_jobs_user FOREIGN KEY (posted_by) REFERENCES users(user_id) ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_jobs_status ON jobs (status);
CREATE INDEX IF NOT EXISTS idx_jobs_posted_by ON jobs (posted_by);
DROP TRIGGER IF EXISTS trg_jobs_updated_at ON jobs;
CREATE TRIGGER trg_jobs_updated_at BEFORE UPDATE ON jobs
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE IF NOT EXISTS job_applications (
  application_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  job_id         BIGINT NOT NULL,
  applicant_id   BIGINT NOT NULL,
  cover_message  VARCHAR(1000) NOT NULL,
  portfolio_url  VARCHAR(255) NULL,
  status         TEXT NOT NULL DEFAULT 'submitted',
  created_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_job_applicant UNIQUE (job_id, applicant_id),
  CONSTRAINT ck_ja_status CHECK (status IN ('submitted','shortlisted','rejected','hired')),
  CONSTRAINT fk_ja_job FOREIGN KEY (job_id) REFERENCES jobs(job_id) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_ja_user FOREIGN KEY (applicant_id) REFERENCES users(user_id) ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE IF NOT EXISTS visions (
  vision_id   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id     BIGINT NOT NULL,
  title       VARCHAR(150) NOT NULL,
  description TEXT NOT NULL,
  category    TEXT NOT NULL DEFAULT 'other',
  status      TEXT NOT NULL DEFAULT 'pending',
  created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT ck_visions_category CHECK (category IN ('education','welfare','event','infrastructure','other')),
  CONSTRAINT ck_visions_status CHECK (status IN ('pending','approved','rejected','implemented')),
  CONSTRAINT fk_visions_user FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_visions_status ON visions (status);
DROP TRIGGER IF EXISTS trg_visions_updated_at ON visions;
CREATE TRIGGER trg_visions_updated_at BEFORE UPDATE ON visions
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE IF NOT EXISTS help_requests (
  help_id     BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id     BIGINT NOT NULL,
  title       VARCHAR(150) NOT NULL,
  description TEXT NOT NULL,
  category    TEXT NOT NULL DEFAULT 'other',
  urgency     TEXT NOT NULL DEFAULT 'medium',
  blood_group TEXT NULL, -- only when category='blood'
  location    VARCHAR(255) NULL, -- where help is needed (required for blood requests)
  required_date DATE NULL, -- when the help/blood is needed (required for blood requests)
  status      TEXT NOT NULL DEFAULT 'open',
  created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT ck_help_category CHECK (category IN ('career','education','medical','financial','blood','other')),
  CONSTRAINT ck_help_urgency CHECK (urgency IN ('low','medium','high','emergency')),
  CONSTRAINT ck_help_blood CHECK (blood_group IS NULL OR blood_group IN ('A+','A-','B+','B-','AB+','AB-','O+','O-')),
  CONSTRAINT ck_help_status CHECK (status IN ('open','in_progress','resolved','closed')),
  CONSTRAINT fk_help_user FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_help_status ON help_requests (status);
DROP TRIGGER IF EXISTS trg_help_requests_updated_at ON help_requests;
CREATE TRIGGER trg_help_requests_updated_at BEFORE UPDATE ON help_requests
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE IF NOT EXISTS events (
  event_id    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  created_by  BIGINT NOT NULL,
  title       VARCHAR(150) NOT NULL,
  description TEXT NULL,
  location    VARCHAR(150) NULL,
  event_date  DATE NOT NULL,
  start_time  TIME NULL,
  end_time    TIME NULL,
  capacity    INTEGER NOT NULL DEFAULT 100,
  image       VARCHAR(255) NULL,
  status      TEXT NOT NULL DEFAULT 'published',
  created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT ck_events_capacity CHECK (capacity >= 0),
  CONSTRAINT ck_events_status CHECK (status IN ('draft','published','cancelled','completed')),
  CONSTRAINT fk_events_user FOREIGN KEY (created_by) REFERENCES users(user_id) ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_events_date ON events (event_date);
DROP TRIGGER IF EXISTS trg_events_updated_at ON events;
CREATE TRIGGER trg_events_updated_at BEFORE UPDATE ON events
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE IF NOT EXISTS event_registrations (
  registration_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  event_id        BIGINT NOT NULL,
  user_id         BIGINT NOT NULL,
  created_at      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_event_user UNIQUE (event_id, user_id),
  CONSTRAINT fk_er_event FOREIGN KEY (event_id) REFERENCES events(event_id) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_er_user FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE IF NOT EXISTS notices (
  notice_id    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  created_by   BIGINT NOT NULL,
  title        VARCHAR(150) NOT NULL,
  body         TEXT NOT NULL,
  status       TEXT NOT NULL DEFAULT 'published',
  published_at TIMESTAMP NULL,
  created_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT ck_notices_status CHECK (status IN ('draft','published','archived')),
  CONSTRAINT fk_notices_user FOREIGN KEY (created_by) REFERENCES users(user_id) ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_notices_status ON notices (status);
DROP TRIGGER IF EXISTS trg_notices_updated_at ON notices;
CREATE TRIGGER trg_notices_updated_at BEFORE UPDATE ON notices
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE IF NOT EXISTS notifications (
  notification_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  recipient_id    BIGINT NOT NULL,
  title           VARCHAR(150) NOT NULL,
  message         VARCHAR(500) NOT NULL,
  -- Centralized types (backend/src/services/notificationService.js NOTIFICATION_TYPES).
  -- Legacy values kept for historical rows.
  type            TEXT NOT NULL DEFAULT 'system',
  related_entity_type VARCHAR(30) NULL, -- 'job','event','payment','user',… (reference, never a data copy)
  related_entity_id   BIGINT NULL,
  actor_user_id       BIGINT NULL, -- who triggered the notification (nullable)
  is_read         SMALLINT NOT NULL DEFAULT 0,
  read_at         TIMESTAMP NULL,
  created_at      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT ck_notif_type CHECK (type IN (
    'approval','job','application','event','notice','promotion','demotion','system',
    'new_notice','new_job','new_event','new_vision','new_help','new_poll',
    'registration_pending','registration_approved','registration_rejected',
    'payment_pending','payment_approved','payment_rejected',
    'job_pending','job_approved','job_rejected',
    'vision_pending','vision_approved','vision_rejected','vision_implemented',
    'help_status',
    'gallery_pending','gallery_approved','gallery_rejected',
    'contribution_setup','contribution_updated')),
  CONSTRAINT ck_notif_is_read CHECK (is_read IN (0,1)),
  CONSTRAINT fk_notif_user FOREIGN KEY (recipient_id) REFERENCES users(user_id) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_notif_actor FOREIGN KEY (actor_user_id) REFERENCES users(user_id) ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_notif_recipient ON notifications (recipient_id, is_read);
CREATE INDEX IF NOT EXISTS idx_notif_recipient_created ON notifications (recipient_id, created_at);
CREATE INDEX IF NOT EXISTS idx_notif_dedupe ON notifications (type, related_entity_type, related_entity_id, created_at);

CREATE TABLE IF NOT EXISTS polls (
  poll_id    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  created_by BIGINT NOT NULL,
  question   VARCHAR(255) NOT NULL,
  status     TEXT NOT NULL DEFAULT 'open',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT ck_polls_status CHECK (status IN ('draft','open','closed')),
  CONSTRAINT fk_polls_user FOREIGN KEY (created_by) REFERENCES users(user_id) ON DELETE CASCADE ON UPDATE CASCADE
);
DROP TRIGGER IF EXISTS trg_polls_updated_at ON polls;
CREATE TRIGGER trg_polls_updated_at BEFORE UPDATE ON polls
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE IF NOT EXISTS poll_options (
  option_id   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  poll_id     BIGINT NOT NULL,
  option_text VARCHAR(150) NOT NULL,
  position    INTEGER NOT NULL DEFAULT 0,
  CONSTRAINT ck_po_position CHECK (position >= 0),
  CONSTRAINT fk_po_poll FOREIGN KEY (poll_id) REFERENCES polls(poll_id) ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_po_poll ON poll_options (poll_id);

CREATE TABLE IF NOT EXISTS poll_votes (
  vote_id   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  poll_id   BIGINT NOT NULL,
  option_id BIGINT NOT NULL,
  user_id   BIGINT NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_poll_user UNIQUE (poll_id, user_id),
  CONSTRAINT fk_pv_poll FOREIGN KEY (poll_id) REFERENCES polls(poll_id) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_pv_option FOREIGN KEY (option_id) REFERENCES poll_options(option_id) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_pv_user FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE IF NOT EXISTS gallery (
  gallery_id   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  uploaded_by  BIGINT NOT NULL,
  image_path   VARCHAR(255) NOT NULL,
  caption      VARCHAR(200) NULL,
  status       TEXT NOT NULL DEFAULT 'pending',
  moderated_by BIGINT NULL,
  created_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT ck_gallery_status CHECK (status IN ('pending','approved','rejected')),
  CONSTRAINT fk_gallery_user FOREIGN KEY (uploaded_by) REFERENCES users(user_id) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_gallery_mod FOREIGN KEY (moderated_by) REFERENCES users(user_id) ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_gallery_status ON gallery (status);

CREATE TABLE IF NOT EXISTS teachers (
  teacher_id   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  created_by   BIGINT NULL,
  name         VARCHAR(120) NOT NULL,
  subject      VARCHAR(120) NULL,
  designation  VARCHAR(120) NULL,
  institution  VARCHAR(150) NULL,
  photo        VARCHAR(255) NULL,
  description  VARCHAR(500) NULL,
  created_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_teachers_user FOREIGN KEY (created_by) REFERENCES users(user_id) ON DELETE SET NULL ON UPDATE CASCADE
);
DROP TRIGGER IF EXISTS trg_teachers_updated_at ON teachers;
CREATE TRIGGER trg_teachers_updated_at BEFORE UPDATE ON teachers
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE IF NOT EXISTS audit_logs (
  audit_id   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  actor_id   BIGINT NULL,
  action     VARCHAR(80) NOT NULL,
  entity     VARCHAR(50) NOT NULL,
  entity_id  BIGINT NULL,
  details    JSONB NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_audit_user FOREIGN KEY (actor_id) REFERENCES users(user_id) ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_audit_actor ON audit_logs (actor_id);

-- ---------------------------------------------------------------------
-- Payments — provider-agnostic design.
--   'test'   = simulated charge (records instantly, dev/smoke only)
--   'bkash' / 'nagad' / 'rocket' = MANUAL mobile-money payments:
--     member sends money to the association's number, submits the Transaction
--     ID + optional screenshot; the row stays 'pending' until an admin or the
--     authority approves ('success') or rejects it ('rejected').
-- registration_number is NOT the primary key; users.user_id is the anchor.
-- transaction_id is UNIQUE at the DB level — duplicate submissions are
-- impossible even across concurrent requests.
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS payments (
  payment_id      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id         BIGINT NOT NULL,
  reg_number      VARCHAR(50) NULL, -- snapshot of users.registration_number at payment time
  payment_type    TEXT NOT NULL,
  purpose         TEXT NULL,
  event_id        BIGINT NULL,
  amount          DECIMAL(10,2) NOT NULL,
  payment_method  TEXT NOT NULL DEFAULT 'test',
  sender_number   VARCHAR(20) NULL,
  transaction_id  VARCHAR(64) NOT NULL,
  payment_date    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  billing_month   CHAR(7) NULL, -- 'YYYY-MM' billing period for monthly payments (kept separate from payment_date)
  screenshot_path VARCHAR(255) NULL, -- optional uploaded payment screenshot (filename served under /uploads)
  status          TEXT NOT NULL DEFAULT 'pending',
  description     VARCHAR(255) NULL,
  review_note     VARCHAR(255) NULL, -- admin/authority note written at approval or rejection
  reviewed_by     BIGINT NULL,
  reviewed_at     TIMESTAMP NULL,
  created_at      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_payments_txn UNIQUE (transaction_id),
  CONSTRAINT ck_payments_type CHECK (payment_type IN ('monthly','occasional')),
  CONSTRAINT ck_payments_purpose CHECK (purpose IS NULL OR purpose IN ('event_contribution','donation','help_fund','emergency_fund','other')),
  CONSTRAINT ck_payments_method CHECK (payment_method IN ('test','bkash','nagad','rocket')),
  CONSTRAINT ck_payments_status CHECK (status IN ('pending','success','failed','cancelled','refunded','rejected')),
  CONSTRAINT fk_payments_user FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_payments_event FOREIGN KEY (event_id) REFERENCES events(event_id) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT fk_payments_reviewer FOREIGN KEY (reviewed_by) REFERENCES users(user_id) ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_payments_user ON payments (user_id);
CREATE INDEX IF NOT EXISTS idx_payments_type ON payments (payment_type);
CREATE INDEX IF NOT EXISTS idx_payments_status ON payments (status);
CREATE INDEX IF NOT EXISTS idx_payments_date ON payments (payment_date);
CREATE INDEX IF NOT EXISTS idx_payments_billing_month ON payments (billing_month);
DROP TRIGGER IF EXISTS trg_payments_updated_at ON payments;
CREATE TRIGGER trg_payments_updated_at BEFORE UPDATE ON payments
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- One row per paid month. UNIQUE(user_id, payment_month) makes duplicate
-- monthly payments for the same member + month impossible at the DB level.
CREATE TABLE IF NOT EXISTS monthly_payment_details (
  id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  payment_id      BIGINT NOT NULL,
  user_id         BIGINT NOT NULL,
  payment_month   CHAR(7) NOT NULL, -- normalized 'YYYY-MM'
  amount          DECIMAL(10,2) NOT NULL, -- actual amount received for this month
  extra_amount    DECIMAL(10,2) NOT NULL DEFAULT 0, -- portion above the month's contribution rate
  created_at      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  -- One payment can settle several months (oldest dues first) and a partially
  -- settled month can be topped up by a later payment, so this is an INDEX, not
  -- UNIQUE. Duplicate allocation is prevented by the allocation planner.
  CONSTRAINT fk_mpd_payment FOREIGN KEY (payment_id) REFERENCES payments(payment_id) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_mpd_user FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_monthly_user_month ON monthly_payment_details (user_id, payment_month);
CREATE INDEX IF NOT EXISTS idx_monthly_payment ON monthly_payment_details (payment_id);

-- ---------------------------------------------------------------------
-- Monthly contribution RATES — append-only history, one row per
-- (member, effective month). A rate governs every month from its
-- effective_month until the next rate's effective_month. Previous rows are
-- never overwritten or deleted, so historic dues keep their historic rates.
--   source='reconciliation' rows are reconstructed by npm run
--   migrate:contributions from amounts members ACTUALLY paid (reported).
-- ---------------------------------------------------------------------
-- ATTRIBUTION RETENTION: set_by points at the account that set the rate.
-- When that account is deleted, ON DELETE SET NULL releases the pointer while
-- the row (and its amount/effective_month) survives untouched; the setter's
-- identity text is captured in set_by_snapshot at deletion time, so history is
-- never silently discarded. The rate's OWNER is user_id — never set_by.
-- (In PostgreSQL this behavior is native: no separate migration script needed.)
CREATE TABLE IF NOT EXISTS member_monthly_rates (
  rate_id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id         BIGINT NOT NULL,
  amount          DECIMAL(10,2) NOT NULL,
  effective_month CHAR(7) NOT NULL, -- 'YYYY-MM' — first month this rate applies to
  source          TEXT NOT NULL DEFAULT 'member',
  set_by          BIGINT NULL, -- setter's account; NULL once that account is deleted
  set_by_snapshot VARCHAR(160) NULL, -- 'Name <email> (user_id N)' of the setter, kept when the account is deleted
  created_at      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_mmr_user_effective UNIQUE (user_id, effective_month),
  CONSTRAINT ck_mmr_source CHECK (source IN ('member','admin','reconciliation')),
  CONSTRAINT fk_mmr_user FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_mmr_setby FOREIGN KEY (set_by) REFERENCES users(user_id) ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_mmr_user ON member_monthly_rates (user_id, effective_month);
CREATE INDEX IF NOT EXISTS idx_mmr_setby ON member_monthly_rates (set_by);

